import json
import logging

import boto3

client = boto3.client("lambda")
client_iot = boto3.client("iot-data", region_name="us-east-1")

logger = logging.getLogger()
logger.setLevel(logging.INFO)


def lambda_handler(event, context):
    logger.info("event: %s", event)

    stage = event["context"]["stage"]
    if stage == "smartlybrasil_prod":
        stage = "prod"

    scenarioId = int(event["params"]["path"]["scenarioId"])
    devices = event["body-json"]["devices"] if "devices" in event["body-json"] else None

    responseFromScenario = client.invoke(
        FunctionName=f"smartly_verify_scenario_sc_{stage}",
        InvocationType="RequestResponse",
        Payload=json.dumps(event),
    )

    smartlyControllers = json.load(responseFromScenario["Payload"])
    logger.info("smartlyControllers: %s", smartlyControllers)

    updateList = list()
    if "status" not in smartlyControllers:
        for smartlyControl in smartlyControllers:
            update = False
            config = json.loads(smartlyControl["parameters"])
            for button, parameters in config["config"]["buttons"].items():
                logger.info("parameters: %s", parameters)
                if "scenarioId" in parameters:
                    if parameters["scenarioId"] == scenarioId:
                        update = True
                        logger.info("Encontrou mesmo Cenario: %s", scenarioId)
                        if devices is None:
                            logger.info("Deletando cenário: %s", scenarioId)
                            config["config"]["buttons"][button] = {
                                "name": "Comando " + button,
                                "scenarioId": [-1],
                                "color": [[255, 255, 255]],
                            }

                        else:
                            config["config"]["buttons"][button]["name"] = event[
                                "body-json"
                            ]["name"]
                    else:
                        pass

            logger.info("Config: %s", config)

            if update:
                updateList.append({"smartlyId": smartlyControl["smartlyId"]})
                shadow_payload = {"state": {"desired": config}}
                logger.info("shadow_payload: %s", shadow_payload)
                client_iot.publish(
                    topic=f"$aws/things/{smartlyControl['smartlyId']}/shadow/name/config/update",
                    qos=1,
                    payload=json.dumps(shadow_payload),
                )

        for item in updateList:
            logger.info("smartlyControl: %s", item["smartlyId"])
            shadowResponse = client_iot.publish(
                topic="$aws/things/" + item["smartlyId"] + "/shadow/name/config/get",
                qos=1,
                payload=json.dumps({}),
            )
            logger.info("ShadowResponse: %s", shadowResponse)
    return {"message": "Cenário atualizado com sucesso"}

import json
import logging

import boto3
from botocore.exceptions import ClientError

client = boto3.client("lambda")
client_iot = boto3.client("iot-data", region_name="us-east-1")

logger = logging.getLogger()
logger.setLevel(logging.INFO)


def lambda_handler(event, context):
    logger.info("event: %s", event)

    stage = event["context"]["stage"]
    if stage == "smartlybrasil_prod":
        stage = "prod"

    responseFromChild = client.invoke(
        FunctionName=f"smartly_verify_scenario_lg_{stage}",
        InvocationType="RequestResponse",
        Payload=json.dumps(event),
    )
    response = json.load(responseFromChild["Payload"])

    devices = event.get("body-json", {}).get("devices")

    if not devices:
        devices = delete_scenario(event, response)
        event["body-json"]["devices"] = devices
    else:
        event = update_scenario(event, response)

    responseFromChildVerify = client.invoke(
        FunctionName=f"smartly_verify_connection_to_send_scenario_{stage}",
        InvocationType="RequestResponse",
        Payload=json.dumps(event),
    )
    response = json.load(responseFromChildVerify["Payload"])
    logger.info("response: %s", response)

    return {"statusCode": 200, "body": json.dumps("Hello from Lambda!")}


def update_scenario(event, response):
    scenario_id = event["params"]["path"]["scenarioId"]
    scenario_name = event["body-json"]["name"]

    for device in response:
        smartly_id = device["smartlyId"]

        config = get_device_scenario_config(smartly_id)

        if "scenarios" not in config:
            config["scenarios"] = []

        device_found = next(
            (
                d
                for d in event["body-json"].get("devices", [])
                if d["smartlyId"] == smartly_id
            ),
            None,
        )

        if device_found:
            scenario_json = {"scenarioId": scenario_id, "name": scenario_name}

            VALID_FIELDS = [
                "power",
                "intensity",
                "setpoint",
                "hum_setpoint",
                "animationMode",
                "primaryColor",
                "secondaryColor",
                "animationScale",
                "animationSpeed",
            ]
            device_found = device_found.get("config", {})

            for field in VALID_FIELDS:
                value = device_found.get(field)
                if value is not None:
                    scenario_json[field] = value

            update_or_add_scenario(config, scenario_json)
        else:
            remove_scenario(config, scenario_id)
            event["body-json"]["devices"].append(
                {"smartlyId": smartly_id, "scenarioDeleted": 1}
            )

        publish_device_update_scenario_config(smartly_id, config)

    return event


def delete_scenario(event, response):
    scenario_id = event["params"]["path"]["scenarioId"]
    devices = []

    for device in response:
        smartly_id = device["smartlyId"]
        config = get_device_scenario_config(smartly_id)

        if remove_scenario(config, scenario_id):
            devices.append({"smartlyId": smartly_id})

        publish_device_update_scenario_config(smartly_id, config)

    return devices


def get_device_scenario_config(smartly_id):
    try:
        logger.info("smartly_id: %s", smartly_id)
        shadow_response = client_iot.get_thing_shadow(
            thingName=smartly_id, shadowName="scenarioConfig"
        )
        shadow = json.loads(shadow_response["payload"].read())

        if "config" not in shadow.get("state", {}).get("desired", {}):
            logger.info("Configuração não encontrada no shadow.")
            return {}

        return shadow["state"]["desired"]["config"]

    except client_iot.exceptions.ResourceNotFoundException:
        logger.info("Shadow 'scenarioConfig' não encontrado para o thing '%s'.", smartly_id)
        return {}

    except ClientError as e:
        logger.info("Erro ao acessar o shadow: %s", e)
        return {}

    except json.JSONDecodeError as e:
        logger.info("Erro ao decodificar o payload do shadow: %s", e)
        return {}

    except Exception as e:
        logger.info("Erro inesperado: %s", e)
        return {}


def update_or_add_scenario(config, scenario_json):
    scenarios = config["scenarios"]
    scenario_json["scenarioId"] = str(scenario_json["scenarioId"])
    for scenario in scenarios:
        scenario["scenarioId"] = str(scenario["scenarioId"])

    existing_scenario = next(
        (
            s
            for s in scenarios
            if str(s["scenarioId"]) == str(scenario_json["scenarioId"])
        ),
        None,
    )

    if existing_scenario:
        index = scenarios.index(existing_scenario)
        scenarios[index] = scenario_json
    else:
        scenarios.append(scenario_json)


def remove_scenario(config, scenario_id):
    scenarios = config["scenarios"]
    scenario_to_remove = next(
        (s for s in scenarios if str(s["scenarioId"]) == str(scenario_id)), None
    )

    if scenario_to_remove:
        scenarios.remove(scenario_to_remove)
        return True
    return False


def publish_device_update_config(smartly_id, config):
    shadow_payload = {"state": {"desired": {"config": config}}}
    client_iot.publish(
        topic=f"$aws/things/{smartly_id}/shadow/name/config/update",
        qos=1,
        payload=json.dumps(shadow_payload),
    )


def publish_device_update_scenario_config(smartly_id, config):
    shadow_payload = {"state": {"desired": {"config": config}}}
    client_iot.publish(
        topic=f"$aws/things/{smartly_id}/shadow/name/scenarioConfig/update",
        qos=1,
        payload=json.dumps(shadow_payload),
    )

import json
import boto3
import random
import time

client_iot = boto3.client("iot-data", region_name="us-east-1")
client = boto3.client("lambda")


def lambda_handler(event, context):
    print("Event: ", event)

    stage = event["context"]["stage"]
    if stage == "smartlybrasil_prod":
        stage = "prod"

    responseFromScenario = client.invoke(
        FunctionName=f"smartly_verify_scenario_sc_{stage}",
        InvocationType="RequestResponse",
        Payload=json.dumps(event),
    )

    smartlyControllers = json.load(responseFromScenario["Payload"])

    print("smartlyControllers: ", smartlyControllers)

    for deviceIndex in event["body-json"]["devices"]:
        scenarioId = event["params"]["path"]["scenarioId"]
        token = random.randint(1, 65535)
        shadowPayload = {
            "scenarioId": -1
            if "scenarioDeleted" in event["params"]["path"]
            else scenarioId,
            "token": token,
        }
        print("shadowPayload: ", shadowPayload)
        print("deviceIndex: ", deviceIndex)

        if "config" in deviceIndex:
            if "power" in deviceIndex["config"]:
                shadowPayload["power"] = deviceIndex["config"]["power"]
            if "intensity" in deviceIndex["config"]:
                shadowPayload["intensity"] = deviceIndex["config"]["intensity"]
            if "setpoint" in deviceIndex["config"]:
                shadowPayload["setpoint"] = deviceIndex["config"]["setpoint"]
            if "hum_setpoint" in deviceIndex["config"]:
                shadowPayload["hum_setpoint"] = deviceIndex["config"]["hum_setpoint"]
        else:
            shadowPayload["power"] = -1
        smartlyId = deviceIndex["smartlyId"]

        if smartlyId.startswith("SmartLy-lg"):
            shadowResponse = client_iot.get_thing_shadow(
                thingName=smartlyId, shadowName="lighting"
            )
            prefixRemove = smartlyId.replace("SmartLy-lg-", "")
        elif smartlyId.startswith("SmartLy-th"):
            shadowResponse = client_iot.get_thing_shadow(
                thingName=smartlyId, shadowName="thermostat"
            )
            prefixRemove = smartlyId.replace("SmartLy-th-", "")
        elif smartlyId.startswith("SmartLy-hc"):
            shadowResponse = client_iot.get_thing_shadow(
                thingName=smartlyId, shadowName="hotcloset"
            )
            prefixRemove = smartlyId.replace("SmartLy-hc-", "")
        elif smartlyId.startswith("SmartLy-sc"):
            shadowResponse = client_iot.get_thing_shadow(
                thingName=smartlyId, shadowName="smartlycontrol"
            )
            prefixRemove = smartlyId.replace("SmartLy-sc-", "")
        shadow = json.loads(shadowResponse["payload"].read())
        shadowPayload["id"] = prefixRemove

        if shadow["state"]["desired"]["status"] == "disconnected":
            print("Shadow: ", shadow)

            for sc in smartlyControllers:
                print("sc: ", sc)
                string = json.dumps(shadowPayload)
                shadowResponse = client_iot.publish(
                    topic=sc["smartlyId"] + "/scenario", qos=1, payload=string
                )
            time.sleep(0.5)
    return {"statusCode": 200, "body": json.dumps("Hello from Lambda!")}

import json
import boto3

client = boto3.client("lambda")


def lambda_handler(event, context):
    print(event)

    stage = event["context"]["stage"]
    if stage == "smartlybrasil_prod":
        stage = "prod"

    deviceId = int(event["deviceId"])

    responseFromChild = client.invoke(
        FunctionName=f"smartly_get_local_scenarios_{stage}",
        InvocationType="RequestResponse",
        Payload=json.dumps(event),
    )

    response = json.load(responseFromChild["Payload"])

    for scenario in response:
        scenario["devices"] = json.loads(scenario["devices"])
        for index, device in enumerate(scenario["devices"]):
            if device["id"] == deviceId:
                del scenario["devices"][index]
                payload = {
                    "context": {"stage": event["context"]["stage"]},
                    "params": {
                        "path": {
                            "localId": event["localId"],
                            "scenarioId": scenario["id"],
                        }
                    },
                    "body-json": {
                        "userId": event["userId"],
                        "name": scenario["name"],
                        "image": scenario["image"],
                        "devices": scenario["devices"],
                    },
                }
                print("payload: ", payload)
                responseFromChild = client.invoke(
                    FunctionName=f"smartly_parent_update_scenario_{stage}",
                    InvocationType="Event",
                    Payload=json.dumps(payload),
                )
                print("Cenário atualizado: ", scenario["id"])
